META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–2: ಜ್ಞಾನ ಶ್ರೇಷ್ಠವಾದರೆ ಯುದ್ಧ ಏಕೆ ಎಂದು ಅರ್ಜುನ ಕೇಳುತ್ತಾನೆ; 3–9: ಯಾರೂ ಕರ್ಮ ಮಾಡದೆ ಇರಲಾರರು, ಯಜ್ಞಕ್ಕಾಗಿ ಮಾಡುವ ಕರ್ಮ ಬಂಧಿಸುವುದಿಲ್ಲ; 10–16: ಯಜ್ಞದ ಚಕ್ರ; 17–26: ಜ್ಞಾನಿಯೂ ಲೋಕಹಿತಕ್ಕಾಗಿ ಕರ್ಮ ಮಾಡುತ್ತಾನೆ, ಜನಕನಂತೆ; 27–35: ಗುಣಗಳೇ ಕರ್ಮ ಮಾಡುತ್ತವೆ, ಸ್ವಧರ್ಮವೇ ಶ್ರೇಷ್ಠ; 36–43: ಕಾಮವೇ ಶತ್ರು, ಅದನ್ನು ಹೇಗೆ ಗೆಲ್ಲುವುದು.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಜನಾರ್ದನ, ಕರ್ಮಕ್ಕಿಂತ ಬುದ್ಧಿ (ಜ್ಞಾನ) ಶ್ರೇಷ್ಠ ಎಂದು ನೀವು ಭಾವಿಸುವುದಾದರೆ, ಹೇ ಕೇಶವ, ಈ ಘೋರ ಕರ್ಮದಲ್ಲಿ ನನ್ನನ್ನು ಏಕೆ ತೊಡಗಿಸುತ್ತಿದ್ದೀರಿ?',
2: 'ಗೊಂದಲದಂತೆ ಕಾಣುವ ಮಾತುಗಳಿಂದ ನನ್ನ ಬುದ್ಧಿಯನ್ನು ಮೋಹಗೊಳಿಸುತ್ತಿರುವಂತೆ ಅನಿಸುತ್ತದೆ. ಯಾವುದರಿಂದ ನಾನು ಶ್ರೇಯಸ್ಸನ್ನು ಪಡೆಯುತ್ತೇನೋ ಆ ಒಂದನ್ನೇ ನಿಶ್ಚಯವಾಗಿ ಹೇಳಿ.',
3: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾಪರಹಿತ, ಈ ಲೋಕದಲ್ಲಿ ಎರಡು ಬಗೆಯ ನಿಷ್ಠೆಯನ್ನು ನಾನು ಹಿಂದೆಯೇ ಹೇಳಿದ್ದೇನೆ: ಸಾಂಖ್ಯರಿಗೆ ಜ್ಞಾನಯೋಗ, ಯೋಗಿಗಳಿಗೆ ಕರ್ಮಯೋಗ.',
4: 'ಕರ್ಮಗಳನ್ನು ಆರಂಭಿಸದೆ ಇರುವುದರಿಂದ ಮನುಷ್ಯ ನೈಷ್ಕರ್ಮ್ಯವನ್ನು ಪಡೆಯುವುದಿಲ್ಲ, ಕೇವಲ ತ್ಯಜಿಸುವುದರಿಂದ ಸಿದ್ಧಿಯನ್ನೂ ಪಡೆಯುವುದಿಲ್ಲ.',
5: 'ಯಾರೂ ಒಂದು ಕ್ಷಣವೂ ಕರ್ಮ ಮಾಡದೆ ಇರಲಾರರು. ಪ್ರಕೃತಿಯಿಂದ ಹುಟ್ಟಿದ ಗುಣಗಳು ಎಲ್ಲರನ್ನೂ ಅಸಹಾಯಕರಾಗಿ ಕರ್ಮದಲ್ಲಿ ತೊಡಗಿಸುತ್ತವೆ.',
6: 'ಕರ್ಮೇಂದ್ರಿಯಗಳನ್ನು ಹಿಡಿದಿಟ್ಟು, ಮನಸ್ಸಿನಲ್ಲಿ ಇಂದ್ರಿಯ ವಿಷಯಗಳನ್ನೇ ಚಿಂತಿಸುತ್ತಾ ಕುಳಿತಿರುವ ಮೂಢನನ್ನು ಕಪಟಿ ಎನ್ನುತ್ತಾರೆ.',
7: 'ಆದರೆ ಹೇ ಅರ್ಜುನ, ಮನಸ್ಸಿನಿಂದ ಇಂದ್ರಿಯಗಳನ್ನು ನಿಯಂತ್ರಿಸಿ, ಆಸಕ್ತಿಯಿಲ್ಲದೆ ಕರ್ಮೇಂದ್ರಿಯಗಳಿಂದ ಕರ್ಮಯೋಗವನ್ನು ಆರಂಭಿಸುವವನು ಶ್ರೇಷ್ಠನು.',
8: 'ನಿನ್ನ ನಿಯತ ಕರ್ಮವನ್ನು ಮಾಡು; ಕರ್ಮ ಮಾಡದಿರುವುದಕ್ಕಿಂತ ಕರ್ಮ ಮಾಡುವುದು ಶ್ರೇಷ್ಠ. ಕರ್ಮವಿಲ್ಲದೆ ನಿನ್ನ ದೇಹಯಾತ್ರೆಯೂ ನಡೆಯಲಾರದು.',
9: 'ಯಜ್ಞಕ್ಕಾಗಿ ಮಾಡುವ ಕರ್ಮವನ್ನು ಬಿಟ್ಟು ಬೇರೆ ಕರ್ಮಗಳಿಂದ ಈ ಲೋಕ ಬಂಧಿಸಲ್ಪಡುತ್ತದೆ. ಹೇ ಕೌಂತೇಯ, ಆಸಕ್ತಿಯಿಲ್ಲದೆ ಆ ಯಜ್ಞಕ್ಕಾಗಿ ಕರ್ಮ ಮಾಡು.',
10: 'ಆದಿಯಲ್ಲಿ ಪ್ರಜಾಪತಿ ಯಜ್ಞದೊಂದಿಗೆ ಪ್ರಜೆಗಳನ್ನು ಸೃಷ್ಟಿಸಿ ಹೇಳಿದನು: "ಇದರಿಂದ ನೀವು ಅಭಿವೃದ್ಧಿ ಹೊಂದಿ, ಇದು ನಿಮ್ಮ ಬಯಕೆಗಳನ್ನು ಈಡೇರಿಸುವ ಕಾಮಧೇನುವಾಗಲಿ.',
11: 'ಇದರಿಂದ ನೀವು ದೇವತೆಗಳನ್ನು ತೃಪ್ತಿಪಡಿಸಿ, ದೇವತೆಗಳು ನಿಮ್ಮನ್ನು ತೃಪ್ತಿಪಡಿಸಲಿ. ಹೀಗೆ ಪರಸ್ಪರ ಪೋಷಿಸುತ್ತಾ ನೀವು ಪರಮ ಶ್ರೇಯಸ್ಸನ್ನು ಪಡೆಯುವಿರಿ.',
12: 'ಯಜ್ಞದಿಂದ ತೃಪ್ತರಾದ ದೇವತೆಗಳು ನಿಮಗೆ ಬೇಕಾದ ಭೋಗಗಳನ್ನು ಕೊಡುತ್ತಾರೆ." ಅವರು ಕೊಟ್ಟದ್ದನ್ನು ಅವರಿಗೆ ಅರ್ಪಿಸದೆ ಅನುಭವಿಸುವವನು ಕಳ್ಳನೇ ಸರಿ.',
13: 'ಯಜ್ಞದಲ್ಲಿ ಉಳಿದುದನ್ನು ತಿನ್ನುವ ಸಜ್ಜನರು ಎಲ್ಲ ಪಾಪಗಳಿಂದ ಮುಕ್ತರಾಗುತ್ತಾರೆ. ತಮಗಾಗಿಯೇ ಅಡುಗೆ ಮಾಡುವ ಪಾಪಿಗಳು ಪಾಪವನ್ನೇ ತಿನ್ನುತ್ತಾರೆ.',
14: 'ಜೀವಿಗಳು ಅನ್ನದಿಂದ ಹುಟ್ಟುತ್ತವೆ, ಅನ್ನ ಮಳೆಯಿಂದ ಹುಟ್ಟುತ್ತದೆ, ಮಳೆ ಯಜ್ಞದಿಂದ ಆಗುತ್ತದೆ, ಯಜ್ಞ ಕರ್ಮದಿಂದ ಹುಟ್ಟುತ್ತದೆ.',
15: 'ಕರ್ಮ ವೇದದಿಂದ ಹುಟ್ಟಿದೆ ಎಂದು ತಿಳಿ, ವೇದ ಅಕ್ಷರ (ಪರಮಾತ್ಮ)ನಿಂದ ಹುಟ್ಟಿದೆ. ಆದ್ದರಿಂದ ಸರ್ವವ್ಯಾಪಿ ಬ್ರಹ್ಮ ಸದಾ ಯಜ್ಞದಲ್ಲಿ ನೆಲೆಸಿದೆ.',
16: 'ಹೇ ಪಾರ್ಥ, ಹೀಗೆ ತಿರುಗುತ್ತಿರುವ ಈ ಚಕ್ರವನ್ನು ಇಲ್ಲಿ ಅನುಸರಿಸದೆ, ಇಂದ್ರಿಯಸುಖದಲ್ಲಿ ಮುಳುಗಿ ಪಾಪಮಯ ಜೀವನ ನಡೆಸುವವನು ವ್ಯರ್ಥವಾಗಿ ಬದುಕುತ್ತಾನೆ.',
17: 'ಆದರೆ ಆತ್ಮದಲ್ಲೇ ಆನಂದಿಸುವ, ಆತ್ಮದಲ್ಲೇ ತೃಪ್ತನಾದ, ಆತ್ಮದಲ್ಲೇ ಸಂತುಷ್ಟನಾದ ಮನುಷ್ಯನಿಗೆ ಮಾಡಬೇಕಾದ ಕರ್ತವ್ಯ ಯಾವುದೂ ಇಲ್ಲ.',
18: 'ಅವನಿಗೆ ಈ ಲೋಕದಲ್ಲಿ ಕರ್ಮ ಮಾಡುವುದರಿಂದ ಯಾವ ಲಾಭವೂ ಇಲ್ಲ, ಮಾಡದಿರುವುದರಿಂದ ಯಾವ ನಷ್ಟವೂ ಇಲ್ಲ. ಯಾವ ಜೀವಿಯ ಮೇಲೂ ಅವನಿಗೆ ಯಾವ ಸ್ವಾರ್ಥದ ಅವಲಂಬನೆಯೂ ಇಲ್ಲ.',
19: 'ಆದ್ದರಿಂದ ಆಸಕ್ತಿಯಿಲ್ಲದೆ, ಮಾಡಬೇಕಾದ ಕರ್ಮವನ್ನು ಸದಾ ಚೆನ್ನಾಗಿ ಮಾಡು. ಆಸಕ್ತಿಯಿಲ್ಲದೆ ಕರ್ಮ ಮಾಡುವ ಮನುಷ್ಯ ಪರಮಾತ್ಮನನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
20: 'ಜನಕ ಮುಂತಾದವರು ಕರ್ಮದಿಂದಲೇ ಸಿದ್ಧಿಯನ್ನು ಪಡೆದರು. ಲೋಕಸಂಗ್ರಹವನ್ನು (ಲೋಕದ ಹಿತವನ್ನು) ಗಮನಿಸಿಯಾದರೂ ನೀನು ಕರ್ಮ ಮಾಡಬೇಕು.',
22: 'ಹೇ ಪಾರ್ಥ, ಮೂರು ಲೋಕಗಳಲ್ಲಿ ನಾನು ಮಾಡಬೇಕಾದ್ದು ಏನೂ ಇಲ್ಲ, ಪಡೆಯಬೇಕಾದ್ದು ಪಡೆಯದೆ ಉಳಿದಿಲ್ಲ, ಆದರೂ ನಾನು ಕರ್ಮದಲ್ಲಿ ತೊಡಗಿದ್ದೇನೆ.',
23: 'ಹೇ ಪಾರ್ಥ, ನಾನು ಎಂದಾದರೂ ಎಚ್ಚರಿಕೆಯಿಂದ ಕರ್ಮದಲ್ಲಿ ತೊಡಗದಿದ್ದರೆ, ಮನುಷ್ಯರು ಎಲ್ಲ ರೀತಿಯಲ್ಲೂ ನನ್ನ ದಾರಿಯನ್ನೇ ಅನುಸರಿಸುತ್ತಾರೆ.',
24: 'ನಾನು ಕರ್ಮ ಮಾಡದಿದ್ದರೆ ಈ ಲೋಕಗಳು ನಾಶವಾಗುತ್ತವೆ. ನಾನು ಗೊಂದಲಕ್ಕೆ ಕಾರಣನಾಗುತ್ತೇನೆ, ಈ ಪ್ರಜೆಗಳನ್ನು ನಾಶಮಾಡಿದವನಾಗುತ್ತೇನೆ.',
25: 'ಹೇ ಭಾರತ, ಅಜ್ಞಾನಿಗಳು ಕರ್ಮದಲ್ಲಿ ಆಸಕ್ತರಾಗಿ ಹೇಗೆ ಕರ್ಮ ಮಾಡುತ್ತಾರೋ, ಜ್ಞಾನಿ ಲೋಕಹಿತವನ್ನು ಬಯಸಿ ಆಸಕ್ತಿಯಿಲ್ಲದೆ ಹಾಗೆಯೇ ಕರ್ಮ ಮಾಡಬೇಕು.',
26: 'ಕರ್ಮದಲ್ಲಿ ಆಸಕ್ತರಾದ ಅಜ್ಞಾನಿಗಳ ಬುದ್ಧಿಯಲ್ಲಿ ಜ್ಞಾನಿ ಗೊಂದಲ ಉಂಟುಮಾಡಬಾರದು. ಸ್ವತಃ ಯೋಗದಿಂದ ಕರ್ಮ ಮಾಡುತ್ತಾ ಅವರನ್ನೂ ಎಲ್ಲ ಕರ್ಮಗಳಲ್ಲಿ ತೊಡಗಿಸಬೇಕು.',
27: 'ಎಲ್ಲ ಕರ್ಮಗಳೂ ಪ್ರಕೃತಿಯ ಗುಣಗಳಿಂದ ನಡೆಯುತ್ತವೆ. ಅಹಂಕಾರದಿಂದ ಮೋಹಗೊಂಡವನು "ನಾನೇ ಕರ್ತ" ಎಂದು ಭಾವಿಸುತ್ತಾನೆ.',
28: 'ಆದರೆ ಹೇ ಮಹಾಬಾಹು, ಗುಣ ಮತ್ತು ಕರ್ಮಗಳ ವಿಭಾಗದ ತತ್ತ್ವವನ್ನು ತಿಳಿದವನು "ಗುಣಗಳೇ ಗುಣಗಳಲ್ಲಿ ವರ್ತಿಸುತ್ತಿವೆ" ಎಂದು ತಿಳಿದು ಆಸಕ್ತನಾಗುವುದಿಲ್ಲ.',
29: 'ಪ್ರಕೃತಿಯ ಗುಣಗಳಿಂದ ಮೋಹಗೊಂಡವರು ಗುಣಗಳ ಕರ್ಮಗಳಲ್ಲಿ ಆಸಕ್ತರಾಗುತ್ತಾರೆ. ಪೂರ್ಣ ತಿಳಿಯದ ಆ ಮಂದಬುದ್ಧಿಗಳನ್ನು ಪೂರ್ಣ ತಿಳಿದವನು ವಿಚಲಿತಗೊಳಿಸಬಾರದು.',
30: 'ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಅಧ್ಯಾತ್ಮ ಬುದ್ಧಿಯಿಂದ ನನಗೆ ಅರ್ಪಿಸಿ, ಆಸೆಯಿಲ್ಲದೆ, "ನನ್ನದು" ಎಂಬ ಭಾವವಿಲ್ಲದೆ, ಮನಸ್ಸಿನ ಜ್ವರವನ್ನು ಬಿಟ್ಟು ಯುದ್ಧ ಮಾಡು.',
31: 'ಶ್ರದ್ಧೆಯಿಂದ, ದೋಷ ಹುಡುಕದೆ ನನ್ನ ಈ ಮತವನ್ನು ಸದಾ ಅನುಸರಿಸುವ ಮನುಷ್ಯರು ಕರ್ಮಗಳಿಂದ ಮುಕ್ತರಾಗುತ್ತಾರೆ.',
32: 'ಆದರೆ ದೋಷ ಹುಡುಕುತ್ತಾ ನನ್ನ ಈ ಮತವನ್ನು ಅನುಸರಿಸದವರನ್ನು, ಎಲ್ಲ ಜ್ಞಾನದಲ್ಲೂ ಮೂಢರಾದ, ವಿವೇಕವಿಲ್ಲದ ಅವರನ್ನು ನಾಶವಾದವರೆಂದು ತಿಳಿ.',
33: 'ಜ್ಞಾನಿಯೂ ತನ್ನ ಪ್ರಕೃತಿಗೆ ತಕ್ಕಂತೆ ವರ್ತಿಸುತ್ತಾನೆ. ಎಲ್ಲ ಜೀವಿಗಳೂ ಪ್ರಕೃತಿಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ; ಬಲವಂತದ ನಿಗ್ರಹದಿಂದ ಏನಾಗುತ್ತದೆ?',
34: 'ಪ್ರತಿಯೊಂದು ಇಂದ್ರಿಯಕ್ಕೂ ಅದರ ವಿಷಯದಲ್ಲಿ ರಾಗ ಮತ್ತು ದ್ವೇಷ ನೆಲೆಸಿವೆ. ಅವುಗಳಿಗೆ ವಶನಾಗಬಾರದು, ಏಕೆಂದರೆ ಅವು ದಾರಿಯಲ್ಲಿನ ಶತ್ರುಗಳು.',
36: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ವಾರ್ಷ್ಣೇಯ, ಹಾಗಾದರೆ ಮನುಷ್ಯ ಬಯಸದಿದ್ದರೂ, ಬಲವಂತವಾಗಿ ಹಿಡಿದು ತಳ್ಳಿದಂತೆ, ಯಾವುದರ ಪ್ರೇರಣೆಯಿಂದ ಪಾಪ ಮಾಡುತ್ತಾನೆ?',
37: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಇದು ಕಾಮ, ಇದು ಕ್ರೋಧ, ರಜೋಗುಣದಿಂದ ಹುಟ್ಟಿದ್ದು. ಇದು ಎಷ್ಟು ತಿಂದರೂ ತೃಪ್ತಿಯಾಗದ್ದು, ಮಹಾಪಾಪಿ. ಇದನ್ನೇ ಇಲ್ಲಿ ಶತ್ರು ಎಂದು ತಿಳಿ.',
38: 'ಹೊಗೆಯಿಂದ ಬೆಂಕಿ, ಧೂಳಿನಿಂದ ಕನ್ನಡಿ, ಗರ್ಭಕೋಶದಿಂದ ಭ್ರೂಣ ಮುಚ್ಚಿರುವಂತೆ, ಇದರಿಂದ ಇದು (ಜ್ಞಾನ) ಮುಚ್ಚಿಹೋಗಿದೆ.',
39: 'ಹೇ ಕೌಂತೇಯ, ಜ್ಞಾನಿಯ ನಿತ್ಯ ಶತ್ರುವಾದ, ಬೆಂಕಿಯಂತೆ ತೃಪ್ತಿಯಾಗದ ಈ ಕಾಮರೂಪದಿಂದ ಜ್ಞಾನ ಮುಚ್ಚಿಹೋಗಿದೆ.',
40: 'ಇಂದ್ರಿಯಗಳು, ಮನಸ್ಸು ಮತ್ತು ಬುದ್ಧಿ ಇದರ ನೆಲೆ ಎನ್ನಲಾಗುತ್ತದೆ. ಇವುಗಳ ಮೂಲಕ ಇದು ಜ್ಞಾನವನ್ನು ಮುಚ್ಚಿ ದೇಹಧಾರಿಯನ್ನು ಮೋಹಗೊಳಿಸುತ್ತದೆ.',
41: 'ಆದ್ದರಿಂದ ಹೇ ಭರತಶ್ರೇಷ್ಠ, ಮೊದಲು ಇಂದ್ರಿಯಗಳನ್ನು ನಿಯಂತ್ರಿಸಿ, ಜ್ಞಾನ ಮತ್ತು ವಿಜ್ಞಾನವನ್ನು ನಾಶಮಾಡುವ ಈ ಪಾಪಿಯನ್ನು ಕೊಂದುಬಿಡು.',
42: 'ಇಂದ್ರಿಯಗಳು ಶ್ರೇಷ್ಠ ಎನ್ನುತ್ತಾರೆ; ಇಂದ್ರಿಯಗಳಿಗಿಂತ ಮನಸ್ಸು ಶ್ರೇಷ್ಠ, ಮನಸ್ಸಿಗಿಂತ ಬುದ್ಧಿ ಶ್ರೇಷ್ಠ; ಬುದ್ಧಿಗಿಂತಲೂ ಶ್ರೇಷ್ಠವಾದುದು ಅವನು (ಆತ್ಮ).',
43: 'ಹೇ ಮಹಾಬಾಹು, ಹೀಗೆ ಬುದ್ಧಿಗಿಂತ ಶ್ರೇಷ್ಠವಾದ ಆತ್ಮನನ್ನು ತಿಳಿದು, ಆತ್ಮದಿಂದ ಮನಸ್ಸನ್ನು ಸ್ಥಿರಗೊಳಿಸಿ, ಕಾಮರೂಪದ ಈ ದುರ್ಜಯ ಶತ್ರುವನ್ನು ಕೊಲ್ಲು.',
}
